'use client';

import { useRouter } from 'next/navigation';
import { useState } from 'react';
import {
  FaSun, FaMoon, FaHeart, FaLaptopHouse, FaUser,
  FaUniversity, FaRobot, FaCalendarAlt,
  FaPeopleArrows,
  FaPersonBooth
} from 'react-icons/fa';

export default function Sidebar() {
  const router = useRouter();
  const [darkMode, setDarkMode] = useState(false);
  const [activeSection, setActiveSection] = useState('Dashboard');
  const [showSubmenu, setShowSubmenu] = useState(false);

  return (
    <aside className="w-52 h-auto bg-blue-950 text-white ps-4 flex flex-col relative shadow-md">
      <div className='flex items-center pt-6'>
        <img src="/images/logo.png" alt="BrainWave" className='h-16 w-15'/>
        <h2 className="text-xl font-bold py-6">BrainWave</h2>
      </div>

      <nav className="mt-5">
        <ul className="flex flex-col space-y-2">

          {/* Profile, Saved Posts, Planner */}
          {[
            { name: 'Profile', icon: <FaUser />, path: '/profile' },
            { name: 'Saved Posts', icon: <FaHeart />, path: '/saved-posts' },
            { name: 'Planner', icon: <FaCalendarAlt />, path: '/planner' },
          ].map((item) => (
            <li
              key={item.name}
              className={`item flex items-center space-x-2 py-4 px-4 cursor-pointer transition-all duration-300 relative z-10 ${
                activeSection === item.name
                  ? 'bg-gray-100 text-blue-950 rounded-l-full translate-x-2 clip-path-side'
                  : 'hover:bg-gray-100 hover:text-blue-950 rounded-l-full'
              }`}
              onClick={() => {
                setActiveSection(item.name);
                router.push(item.path);
              }}
            >
              <span>{item.icon}</span>
              <span>{item.name}</span>
            </li>
          ))}

          {/* Coworking with static position and sub-items */}
          <li className="relative">
            <div
              className={`item flex items-center space-x-2 py-4 px-4 cursor-pointer transition-all duration-300 relative z-10 ${
                activeSection === 'Coworking'
                  ? 'bg-gray-100 text-blue-950 rounded-l-full translate-x-2 clip-path-side'
                  : 'hover:bg-gray-100 hover:text-blue-950 rounded-l-full'
              }`}
              onClick={() => {
                setShowSubmenu(!showSubmenu);
                setActiveSection('Coworking');
              }}
            >
              <FaLaptopHouse />
              <span>Coworking</span>
            </div>

            {showSubmenu && (
              <ul className="pl-10 mt-1 space-y-1 text-sm text-white">
                <li
                  className="item flex items-center space-x-2 py-4 px-4 cursor-pointer transition-all duration-300 relative z-10"
                  onClick={() => router.push('/coworking')}
                >
                  <FaPeopleArrows/>
                  <span>Collaborative Space</span>
                </li>
                <li
                  className="item flex items-center space-x-2 py-4 px-4 cursor-pointer transition-all duration-300 relative z-10"
                  onClick={() => router.push('/soloStuding')}
                >
                  <FaPersonBooth/>
                  <span>Focus Mode</span>
                </li>
              </ul>
            )}
          </li>

          {/* University & AI below coworking */}
          {[
            { name: 'University', icon: <FaUniversity />, path: '/university' },
            { name: 'AI', icon: <FaRobot />, path: '/ai' },
          ].map((item) => (
            <li
              key={item.name}
              className={`item flex items-center space-x-2 py-4 px-4 cursor-pointer transition-all duration-300 relative z-10 ${
                activeSection === item.name
                  ? 'bg-gray-100 text-blue-950 rounded-l-full translate-x-2 clip-path-side'
                  : 'hover:bg-gray-100 hover:text-blue-950 rounded-l-full'
              }`}
              onClick={() => {
                setActiveSection(item.name);
                router.push(item.path);
              }}
            >
              <span>{item.icon}</span>
              <span>{item.name}</span>
            </li>
          ))}
        </ul>
      </nav>

      {/* Optional Dark Mode Toggle */}
      <div className="absolute bottom-5 left-1/2 transform -translate-x-1/2">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="p-2 rounded-full bg-gray-200 dark:bg-gray-700"
        >
          {darkMode ? <FaSun className="text-yellow-500" /> : <FaMoon className="text-gray-800" />}
        </button>
      </div>
    </aside>
  );
}
