'use client';

import { useEffect, useState } from 'react';
import Image from 'next/image';
import {
  FaUserCircle, FaEdit, FaSignOutAlt, FaGraduationCap,
  FaBriefcase, FaChalkboardTeacher, FaUniversity
} from 'react-icons/fa';
import {
  MdEmail, MdSchool, MdInterests
} from 'react-icons/md';
import Sidebar from '@/components/sidebar'; // adjust path if needed
import { getPostsByUser } from '@/lib/post-action';
import EditProfile from '@/components/EditProfile';

interface UserProfile {
  id: number;
  firstName: string;
  lastName?: string;
  email: string;
  role: 'STUDENT' | 'PROFESSOR' | 'ALUMNI';
  profilePicture?: string;
  university?: string;
  formation?: string;
  graduationYear?: string;
  degree?: string;
  interests?: string[];
  occupation?: string;
  subject?: string;
  rank?: string;
}

export default function ProfilePage() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState<Partial<UserProfile>>({});
  const [posts, setPosts] = useState<any[]>([]);

  useEffect(() => {
    const loadProfile = async () => {
      const sessionRes = await fetch('/api/session');
      if (!sessionRes.ok) return;

      const { accessToken } = await sessionRes.json();

      const profileRes = await fetch('http://localhost:4000/user/profile', {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      });

      if (profileRes.ok) {
        const profile = await profileRes.json();
        setUser(profile);
        setFormData(profile);
      }
    };

    loadProfile();
  }, []);
useEffect(() => {
  const loadProfileAndPosts = async () => {
    const sessionRes = await fetch('/api/session');
    if (!sessionRes.ok) return;

    const { accessToken, user } = await sessionRes.json();

    const profileRes = await fetch('http://localhost:4000/user/profile', {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    if (profileRes.ok) {
      const profile = await profileRes.json();
      setUser(profile);
      setFormData(profile);
    }

    // ✅ Fetch posts only after we have the user
    const postsRes = await fetch(`http://localhost:4000/post/user/${user.id}`, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    if (postsRes.ok) {
      const data = await postsRes.json();
      setPosts(data);
    }
  };

  loadProfileAndPosts();
}, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async () => {
    const sessionRes = await fetch('/api/session');
    const { accessToken } = await sessionRes.json();

    const res = await fetch('http://localhost:4000/user/profile', {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${accessToken}`,
      },
      body: JSON.stringify(formData),
    });

    if (res.ok) {
      const updated = await res.json();
      setUser(updated);
      setIsEditing(false);
    }
  };

  const handleLogout = async () => {
    await fetch('/api/auth/logout', { method: 'POST' });
    window.location.href = '/login';
  };

  if (!user) return (
    <div className="flex justify-center items-center min-h-screen">
      <div className="animate-pulse text-gray-500">Loading profile...</div>
    </div>
  );

  const getRoleIcon = () => {
    switch (user.role) {
      case 'STUDENT': return <MdSchool className="text-blue-500" />;
      case 'PROFESSOR': return <FaChalkboardTeacher className="text-purple-500" />;
      case 'ALUMNI': return <FaGraduationCap className="text-green-500" />;
      default: return <FaUserCircle />;
    }
  };

  const getRoleColor = () => {
    switch (user.role) {
      case 'STUDENT': return 'bg-blue-100 text-blue-800';
      case 'PROFESSOR': return 'bg-purple-100 text-purple-800';
      case 'ALUMNI': return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };


  return (
    <div className="min-h-screen bg-gray-100 flex">
      {/* Sidebar */}
      <div className=" absolute h-full ">
        <Sidebar />
      </div>

      {/* Main Content */}
      <main className=" flex-1 py-8 px-4 sm:px-4 lg:px-8">
        <div className="max-w-4xl flex flex-col gap-6 mx-auto">
          {/* Header */}
          <div className="bg-white rounded-xl shadow-md overflow-hidden ">
            <div className="p-6 sm:p-8">
              <div className="flex flex-col sm:flex-row items-start sm:items-center gap-6">
                <div className="relative">
                  {user.profilePicture ? (
                    <Image
                      src={user.profilePicture}
                      alt="Profile"
                      width={120}
                      height={120}
                      className="rounded-full object-cover border-4 border-white shadow-md"
                    />
                  ) : (
                    <FaUserCircle className="w-[120px] h-[120px] text-gray-300" />
                  )}
                  <div className="absolute -bottom-2 -right-2 bg-white rounded-full p-1 shadow-md">
                    <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${getRoleColor()}`}>
                      {getRoleIcon()}
                      <span className="ml-1">{user.role.toLowerCase()}</span>
                    </span>
                  </div>
                </div>

                <div className="flex-1">
                  <div className="flex justify-between items-start">
                    <div className="flex flex-col justify-around">
                      <h1 className="text-2xl font-bold text-gray-900">
                        {user.firstName} {user.lastName || ''}
                      </h1>
                      <div className="flex items-center mt-1 text-gray-600">
                        <MdEmail className="mr-2" />
                        <span>{user.email}</span>
                      </div>
                      {user.university && (
                        <div className="mt-4 flex items-center text-gray-700">
                          <FaUniversity className="mr-2 text-gray-500" />
                          <span>{user.university}</span>
                        </div>
                      )}
                    </div>

                    <div className="flex flex-col justify-items-end gap-2">
                      <button
                        onClick={() => setIsEditing(true)}
                        className="bg-blue-900 hover:bg-gray-100 hover:border-2 hover:border-b-blue-900 hover:text-blue-900 text-white px-4 h-10 rounded-lg font-semibold flex items-center justify-center"
                      >
                        <FaEdit className="mr-2" />
                        Edit
                      </button>
                      <button
                        onClick={handleLogout}
                        className="bg-red-700 hover:bg-white hover:border-2 hover:border-red-900 hover:text-red-900 text-white px-4 h-10 rounded-lg font-semibold flex items-center justify-center"
                      >
                        <FaSignOutAlt className="mr-2" />
                        Logout
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Profile Sections */}
          <div className="flex flex-col md:flex-row gap-6">
            {(user.formation || user.graduationYear || user.degree) && (
              <div className="flex-1 bg-white rounded-xl shadow-md overflow-hidden">
                <div className="p-6">
                  <div className="flex items-center mb-4">
                    <MdSchool className="text-blue-500 text-xl mr-2" />
                    <h2 className="text-lg font-semibold text-gray-900">Education</h2>
                  </div>
                  <div className="space-y-3">
                    {user.formation && (
                      <div>
                        <p className="text-sm text-gray-500">Formation</p>
                        <p className="font-medium">{user.formation}</p>
                      </div>
                    )}
                    {user.degree && (
                      <div>
                        <p className="text-sm text-gray-500">Degree</p>
                        <p className="font-medium">{user.degree}</p>
                      </div>
                    )}
                    {user.graduationYear && (
                      <div>
                        <p className="text-sm text-gray-500">Graduation Year</p>
                        <p className="font-medium">{user.graduationYear?.slice(0, 10)}</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}

            {(user.occupation || user.subject || user.rank) && (
              <div className="flex-1 bg-white rounded-xl shadow-md overflow-hidden">
                <div className="p-6">
                  <div className="flex items-center mb-4">
                    <FaBriefcase className="text-purple-500 text-xl mr-2" />
                    <h2 className="text-lg font-semibold text-gray-900">
                      {user.role === 'PROFESSOR' ? 'Teaching' : 'Professional'} Information
                    </h2>
                  </div>
                  <div className="space-y-3">
                    {user.occupation && (
                      <div>
                        <p className="text-sm text-gray-500">Occupation</p>
                        <p className="font-medium">{user.occupation}</p>
                      </div>
                    )}
                    {user.subject && (
                      <div>
                        <p className="text-sm text-gray-500">Subject</p>
                        <p className="font-medium">{user.subject}</p>
                      </div>
                    )}
                    {user.rank && (
                      <div>
                        <p className="text-sm text-gray-500">Rank</p>
                        <p className="font-medium">{user.rank}</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}

            {user.interests && user.interests.length > 0 && (
              <div className="flex-1 bg-white rounded-xl shadow-md overflow-hidden">
                <div className="p-6">
                  <div className="flex items-center mb-4">
                    <MdInterests className="text-green-500 text-xl mr-2" />
                    <h2 className="text-lg font-semibold text-gray-900">Interests</h2>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {user.interests.map((interest, index) => (
                      <span
                        key={index}
                        className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-green-100 text-green-800"
                      >
                        {interest}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
         <div className="text-center">
          {posts.length > 0 ? (
            <div className="bg-white rounded-xl shadow-md overflow-hidden  p-4">
              <h2 className="text-xl font-semibold mb-4">My Posts</h2>
              <ul className="space-y-2">
                {posts.map((post: any) => (
                  <li key={post.id} className="border-b pb-2">
                    <h3 className="font-bold">{post.title}</h3>
                    <p className="text-sm text-gray-600">{post.description}</p>
                  </li>
                ))}
              </ul>
            </div>
          ) : (
            <div className="bg-white rounded-xl shadow-md overflow-hidden mb-6 p-4 text-gray-500">
              You haven't posted anything yet.
            </div>
          )}
         </div>
        </div>
        <EditProfile
          isOpen={isEditing}
          onClose={() => setIsEditing(false)}
          onSubmit={handleSubmit}
          formData={formData}
          setFormData={setFormData}
          role={user.role}
        />
      </main>
    </div>
  );
}
